        for (unsigned int j = 0; j < numCompsOut; j++) {
            T valueData = bufferData_ptr[j];
            T valueBase = bufferBase_ptr ? bufferBase_ptr[j] : 0;
            vNZDiff.push_back(valueData - valueBase);
        }
        vNZIdx.push_back(idx);
    }

